def load():
    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load()
def regions(grid,bg=0):
    h,w=len(grid),len(grid[0]); out=[]
    seen=[[False]*w for _ in range(h)]
    for i in range(h):
        for j in range(w):
            if grid[i][j]==bg and not seen[i][j]:
                q=deque([(i,j)]); seen[i][j]=True; cells=[]; touch=False
                while q:
                    a,b=q.popleft(); cells.append((a,b))
                    for da,db in ((1,0),(-1,0),(0,1),(0,-1)):
                        na,nb=a+da,b+db
                        if not(0<=na<h and 0<=nb<w) : touch=True; continue
                        if grid[na][nb]==bg and not seen[na][nb]: seen[na][nb]=True; q.append((na,nb))
                if not touch: out.append(cells)
    return out
def transform(grid):
    g=[row[:] for row in grid]
    for cells in regions(grid):
        rs=[c[0] for c in cells]; cs=[c[1] for c in cells]
        hh=max(rs)-min(rs)+1; ww=max(cs)-min(cs)+1
        r=(min(hh,ww)-1)//2
        color=2**(4-r) if 1<=r<=3 else 8
        for a,b in cells: g[a][b]=color
    return g
