from collections import deque
def enclosed_regions(grid, bg=0):
    """Maximal connected same-color regions not touching the grid border, as cell lists."""
    h,w=len(grid),len(grid[0]); out=[]
    seen=[[False]*w for _ in range(h)]
    for i in range(h):
        for j in range(w):
            if grid[i][j]==bg and not seen[i][j]:
                q=deque([(i,j)]); seen[i][j]=True; cells=[]; touch=False
                while q:
                    a,b=q.popleft(); cells.append((a,b))
                    for da,db in ((1,0),(-1,0),(0,1),(0,-1)):
                        na,nb=a+da,b+db
                        if not(0<=na<h and 0<=nb<w): touch=True; continue
                        if grid[na][nb]==bg and not seen[na][nb]: seen[na][nb]=True; q.append((na,nb))
                if not touch: out.append(cells)
    return out

def fill_size_color(grid, bg=0):
    """Fill each enclosed region with a color from its bounding-box half-width: 2^(4-r)."""
    g=[row[:] for row in grid]
    for cells in enclosed_regions(grid,bg):
        rs=[c[0] for c in cells]; cs=[c[1] for c in cells]
        r=(min(max(rs)-min(rs)+1, max(cs)-min(cs)+1)-1)//2
        color=2**(4-r) if 1<=r<=3 else 8
        for a,b in cells: g[a][b]=color
    return g
''')
